import * as React from 'react';
import * as AccordionPrimitive from '@exhuma/core';
import { clsx } from 'clsx';

export interface AccordionProps extends React.ComponentPropsWithoutRef<typeof AccordionPrimitive.Accordion> {
  className?: string;
}

export const Accordion = React.forwardRef<HTMLDivElement, AccordionProps>(
  ({ className, children, ...props }, ref) => (
    <AccordionPrimitive.Accordion
      ref={ref}
      className={clsx(
        'w-full space-y-3',
        className
      )}
      {...props}
    >
      {children}
    </AccordionPrimitive.Accordion>
  )
);
Accordion.displayName = 'Accordion';

